input.script:
() => {
  const textarea = document.querySelector('textarea[aria-label="Wolfram|Alpha 输入栏"]');
  if (!textarea) return 'textarea not found';
  // Use native setter to trigger React's state
  const nativeInputValueSetter = Object.getOwnPropertyDescriptor(window.HTMLTextAreaElement.prototype, 'value').set;
  nativeInputValueSetter.call(textarea, 'projectile motion, v0=30 m/s, theta=45 deg, t=3 s, g=9.8 m/s^2');
  textarea.dispatchEvent(new Event('input', { bubbles: true }));
  return 'set value';
}

() => {
  const form = document.querySelector('form');
  if (form) {
    form.submit();
    return 'submitted form';
  } else {
    // Try clicking the submit button
    const submitBtn = document.querySelector('button[aria-label="计算输入按钮"]');
    if (submitBtn) {
      submitBtn.click();
      return 'clicked submit';
    }
    return 'no form or submit button found';
  }
}

() => {
  const textarea = document.querySelector('textarea[aria-label="WolframAlpha input field"]');
  if (!textarea) return 'textarea not found';

  // Use native setter to trigger React's state
  const nativeInputValueSetter = Object.getOwnPropertyDescriptor(window.HTMLTextAreaElement.prototype, 'value').set;
  nativeInputValueSetter.call(textarea, '30 m/s * cos(45 deg) * 3 s, 30 m/s * sin(45 deg) * 3 s - 0.5 * 9.8 m/s^2 * (3 s)^2, 30 m/s * sin(45 deg) - 9.8 m/s^2 * 3 s, sqrt((30 m/s * cos(45 deg))^2 + (30 m/s * sin(45 deg) - 9.8 m/s^2 * 3 s)^2)');
  textarea.dispatchEvent(new Event('input', { bubbles: true }));
  textarea.dispatchEvent(new Event('change', { bubbles: true }));
  return 'set value: ' + textarea.value;
}
